11	------------------------------------------------------------------------------------------ */
12	require BASE_PATH_INCLUDE."/init/check_login.php";
13	
14	
15	/* Info di ritorno, di default ERROR
16	------------------------------------------------------------------------------------------ */
17	$toReturn = array('status' => 0, 'msg' => '', 'redirect' => '', 'error' => '');
18	
19	
20	/* Dati in arrivo
21	------------------------------------------------------------------------------------------ */
22	$function_code = (!empty($_REQUEST['function_code'])) ? $_REQUEST['function_code'] : '';
23	$itemID = (!empty($_REQUEST['id'])) ? (int)$_REQUEST['id'] : false;
24	$action = (!empty($_REQUEST['action'])) ? $_REQUEST['action'] : false;
25	if (!$action) {
26	    $action = $itemID ? 2 : 1; // insert vs update
27	}
28	
29	
30	/**
31	 * Gestione salvataggio via Handler
32	 */
33	try {
34	    $Handler = $App->create($function_code.'.save');
35	    $itemID = $Handler->save($action, $_REQUEST, $itemID);
36	    if(!$itemID || !is_numeric($itemID)):
37	        throw new Exception('Verifica che tutti i campi siano compilati correttamente');
38	    endif;
39	
40	    $toReturn['status'] = 1;
41	    $toReturn['msg'] = '<h2 class="title_ok"><span class="pre-icon entypo-icon-check"></span>Voce salvata.</h2>';
42	    $toReturn['redirect'] = $Handler->getSaveRedirect($_REQUEST, $itemID) ?: '';
43	
44	} catch (UserException $e) {
45	
46	    // cancello la voce in inserimento
47	    if ($itemID && $action == 1) {
48	        $DeleteHandler = $App->create($function_code.'.delete');
49	        $DeleteHandler->handle($itemID);
50	    }
51	    
52	    $toReturn["msg"] = $e->getMessage();
53	
54	} catch (Exception $e) {
55	    
56	    $App->ErrorLogger->handleException($e);
57	
58	    $toReturn['msg']        = '<h2 class="title_ko"><span class="pre-icon entypo-icon-emoji-sad"></span>Opss, qualcosa è andato storto.</h2><p>Verifica i dati e prova a salvare di nuovo.</p>';
59	    $toReturn['error']      = $e->__toString();
60	
61	}
62	
63	
64	/**
65	 * Risposta
66	 */
67	echo json_encode($toReturn);
68	exit;

