/**
 * Converte un valore di dimensione da php.ini (es. "20M") in byte
 *
 * @param string $value
 * @return int
 */
function iniSizeToBytes($value)
{
    $value = trim((string)$value);
    $bytes = (int)$value;

    switch (strtolower(substr($value, -1))) {
        case 'g': $bytes *= 1024;
        case 'm': $bytes *= 1024;
        case 'k': $bytes *= 1024;
    }

    return $bytes;
}


