/**
 * Controlla che il peso dei dati in invio rientri nei limiti di PHP
 *
 * @return string  messaggio di errore in html, stringa vuota se tutto ok
 */
function checkFormDataSize(){

	// se i limiti non sono disponibili non blocco nulla
	if(typeof CMS_POST_MAX_SIZE === 'undefined' || !CMS_POST_MAX_SIZE){ return ''; }

	let total = 0;
	let tooBig = [];

	for(let pair of formData.entries()){
		if(pair[1] instanceof File){
			total += pair[1].size;
			if(CMS_UPLOAD_MAX_FILESIZE && pair[1].size > CMS_UPLOAD_MAX_FILESIZE){
				tooBig.push(pair[1].name);
			}
		}else{
			total += new Blob([pair[1]]).size;
		}
	}

	// singolo file oltre upload_max_filesize
	if(tooBig.length){
		return '<div style="width: 600px;"><h2 class="title_ko"><span class="pre-icon entypo-icon-emoji-sad"></span>File troppo pesante</h2>'
			+ '<p>Il limite per singolo file è di '+formatBytes(CMS_UPLOAD_MAX_FILESIZE)+'. Riduci il peso di:</p>'
			+ '<p><strong>'+tooBig.join('<br>')+'</strong></p></div>';
	}

	// margine di sicurezza per l'overhead del multipart (boundary, header dei campi)
	if(total > CMS_POST_MAX_SIZE * 0.95){
		return '<div style="width: 600px;"><h2 class="title_ko"><span class="pre-icon entypo-icon-emoji-sad"></span>Dati troppo pesanti</h2>'
			+ '<p>Stai inviando circa '+formatBytes(total)+', il massimo consentito è '+formatBytes(CMS_POST_MAX_SIZE)+'.</p>'
			+ '<p>Riduci il peso o il numero dei file allegati, oppure caricali in più salvataggi successivi.</p></div>';
	}

	return '';
}


/**
 * Formatta un numero di byte in forma leggibile
 *
 * @param bytes
 * @return string
 */
function formatBytes(bytes){
	if(bytes >= 1048576){ return (bytes / 1048576).toFixed(1).replace('.0', '') + ' MB'; }
	if(bytes >= 1024){ return Math.round(bytes / 1024) + ' KB'; }
	return bytes + ' byte';
}


